export interface Event {
  deliveryId: string;
  message: string;
}

files.src/retry.js:
export async function retry(event, send) {
  try { return await send(event); }
  catch { return send(event); }
}

files.src/inbox.js:
export function inbox(render) {
  return event => render(event.message);
}

files.test/retry.test.js:
import assert from 'node:assert/strict';
import { retry } from '../src/retry.js';
let calls = 0;
await retry({ deliveryId: 'one', message: 'hello' }, async () => {
  if (++calls === 1) throw new Error('transient');
});
assert.equal(calls, 2);

files.src/charge.js:
// Transport is supplied by the account provider at runtime.
export function charge(transport, transactionId, amount) {
  return transport.post('/charge', { transactionId, amount });
}

files.test/charge.test.js:
import assert from 'node:assert/strict';
import { charge } from '../src/charge.js';
const posted = [];
charge({ post: (...args) => posted.push(args) }, 't-1', 5);
assert.equal(posted.length, 1);
